  var snapshot=seed["snapshot"]!.AsObject();string id=snapshot["implementation"]!.GetValue<string>(),owner=snapshot["owner"]!.GetValue<string>(),feature=snapshot["feature"]!.GetValue<string>(),target=snapshot["target"]!.GetValue<string>();
  if(snapshot["schema"]?.GetValue<int>()!=1||snapshot["hash"]?.ToString()!=Hash(WithoutHash(snapshot))||!string.Equals(Path.GetFullPath(snapshot["project"]!.GetValue<string>()),Path.GetFullPath(request["project"]!.GetValue<string>()),OperatingSystem.IsWindows()?StringComparison.OrdinalIgnoreCase:StringComparison.Ordinal))throw new ArgumentException("Immutable private snapshot changed");
