  string ns=PackPaths.Namespace(owner);if(id.Length>256||!System.Text.RegularExpressions.Regex.IsMatch(id[(ns.Length+2)..],@"\A[A-Za-z_][A-Za-z_0-9]*\z")||!System.Text.RegularExpressions.Regex.IsMatch(target,@"\A[A-Za-z_][A-Za-z_0-9.-]*\z")||id==owner||id==feature||id==snapshot["source"]?.ToString())throw new ArgumentException("New bounded private implementation/target identity required");if(copy.Kind!="implementation"||copy.Id!=id||PackPaths.Namespace(id)!=ns||fn.Kind!="function"||fn.Id!=feature||copy.Function!=feature||copy.Parent is not null||!copy.Signature!.Matches(fn.Signature)||copy.Bodies.Count!=1||!copy.Bodies.TryGetValue(target,out var body)||body.SourceKind!="blueprint"||body.Path!=snapshot["graphPath"]?.ToString()||body.Path!="blueprints/"+id[(ns.Length+2)..]+".graph.json")throw new ArgumentException("One exact new owned private body required");
