  var records=snapshot["records"]!.AsArray();var ids=new HashSet<string>(StringComparer.Ordinal);foreach(var row in records){string node=row!["id"]!.ToString(),relative=row["relative"]!.ToString();if(!ids.Add(node)||!BlueprintTree.Nodes(graph).Any(e=>e.Key==node&&e.Node["kind"]?.ToString()=="code"&&e.Node["implementation"]?.ToString()==relative)||relative!="nodes/"+id[(ns.Length+2)..]+"."+JsonData.Digest(node)[..12]+".node.json"&&!(node=="body"&&relative=="nodes/"+id[(ns.Length+2)..]+".body.node.json"))throw new ArgumentException("Exact immutable copy record identity/path required");BlueprintDocuments.Validate(BlueprintTree.SourceId(id+"/body:"+target,node),"blueprint-node",row["record"]!.ToJsonString());}
