  string ownerId=snapshot["owner"]!.ToString(),feature=snapshot["feature"]!.ToString(),id=snapshot["implementation"]!.ToString(),target=snapshot["target"]!.ToString();
  foreach(var field in new[]{("owner",ownerId),("feature",feature),("implementation",id),("source",snapshot["source"]!.ToString()),("target",target),("ownerBasisHash",snapshot["ownerHash"]!.ToString()),("scopeGuard",seed["scopeGuard"]!.ToString())})if(request[field.Item1]?.ToString()!=field.Item2)throw new InvalidOperationException("Private selection binding changed ("+field.Item1+"); preserve all input");
