  var copy=new Parser(snapshot["implementationText"]!.GetValue<string>(),"<private-candidate>").ParseElement();var fn=new Parser(snapshot["featureSource"]!.GetValue<string>(),"<private-contract>").ParseElement();var graph=snapshot["graph"]!.DeepClone().AsObject();var records=snapshot["records"]!.DeepClone().AsArray();var baseline=Definitions(snapshot,copy,graph,snapshot["featureContracts"]!.AsObject(),false);var fresh=Definitions(snapshot,copy,graph,contracts,true);
