   string node=row["id"]!.ToString(),called=row["definition"]!["calledFeature"]?.ToString()??graph["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()==node)!["feature"]!.ToString();if(unavailable.Contains(called)||graph["nodes"]!.AsArray().Any(n=>n!["implementationContext"] is not null))continue;
   try{var remapPreview=BlueprintCallAbi.Prepare(new JsonObject{["id"]=id,["text"]=format(copy),["graph"]=graph.DeepClone(),["node"]=node,["signature"]=row["currentCallSignature"]!.DeepClone(),["contractHash"]=row["postCallEditor"]!["contractHash"]!.DeepClone(),["previewRemap"]=true},format);bindings[node]=new JsonObject{["schema"]=1,["seed"]=snapshot["hash"]!.DeepClone(),["guard"]=guard,["owner"]=ownerId,["implementation"]=id,["target"]=target,["source"]=snapshot["source"]!.DeepClone(),["node"]=node,["feature"]=called,["sourceHash"]=row["callAbiSourceHash"]!.DeepClone(),["signature"]=row["currentCallSignature"]!.DeepClone(),["contractHash"]=row["postCallEditor"]!["contractHash"]!.DeepClone(),["receipt"]=receipts[called]?.DeepClone()};if(remapPreview["remap"] is not null)bindings[node]!["remap"]=remapPreview["remap"]!.DeepClone();}catch{}
  }
  if(preview){var view=ImplementationCopy.Project(copy,graph,records,fn,baseline,target,request["privatePath"]?.GetValue<string>()??"");foreach(var row in view["nodes"]!.AsArray()){var now=ImplementationCopyTree.Definition(fresh,(view["privatePath"]!.ToString().Length==0?"":view["privatePath"]!.ToString()+"/")+row!["id"]!.ToString());foreach(string field in new[]{"currentCallSignature","callAbiSourceHash","postCallEditor","postCallSignatureMatches","postCallStale"})row![field]=now[field]?.DeepClone();row!["callAbiAvailable"]=bindings[row["id"]!.ToString()] is not null;row!["callAbiRemap"]=bindings[row["id"]!.ToString()]?["remap"]?.DeepClone();row["privateCopyAbiBinding"]=bindings[row["id"]!.ToString()]?.DeepClone();row["callAbiReceipt"]=bindings[row["id"]!.ToString()]?["receipt"]?.DeepClone();}view["seedHash"]=snapshot["hash"]!.DeepClone();var result=new JsonObject{["preview"]=view,["graph"]=graph,["signature"]=FeatureBlueprint.SignatureDocument(fn.Signature!),["observations"]=current["observations"]!.DeepClone(),["sourceKind"]=snapshot["sourceKind"]!.DeepClone(),["guardHash"]=guard,["seedHash"]=snapshot["hash"]!.DeepClone(),["bodyReads"]=current["bodyReads"]!.DeepClone(),["sourceWritten"]=false,["compiled"]=false};if(initialize){var sealedSeed=seed.DeepClone().AsObject();sealedSeed["initialGuard"]=guard;sealedSeed["hash"]=Hash(WithoutHash(sealedSeed));result["seed"]=sealedSeed;}return result;}
